        "milestone_id": "find_lectern",
        "description": "Uses position_near_with_facing because this is a find/locate/observe task. The agent must navigate close enough to the lectern (within 4 blocks) and face toward it (within 60° tolerance). The lectern is at spawn-relative coordinates (0, 1, 8), centered on the back wall of a cobblestone building 8 blocks ahead of spawn. A max_distance of 4 ensures the agent has walked forward to at least z≈4, meaning they are at or inside the building doorway (entrance at z=5), with clear line of sight to the lectern. This prevents trivial completion from spawn (which is 8 blocks away, well outside the 4-block threshold). The facing_tolerance of 60° confirms the agent is actively looking at the lectern.",
        "rules": [
          {
            "type": "position_near_with_facing",
            "params": {
              "target": [0, 1, 8],
              "max_distance": 4,
              "facing_tolerance": 60,
              "coordinate_frame": "spawn_relative"
            }
          }
        ]
      }
